import { NextResponse } from "next/server";
import {
  appendDevSessionChat,
  appendDevSessionEvents,
  getDevCase,
  getDevSession,
  getDevSessionChat,
  getPostingByToken,
  lifecycleByPosting,
} from "@/app/_lib/db";
import { runSessionChat } from "@/app/_lib/devcase-run";
import { jsonError } from "@/app/_lib/api-response";

// Captured prompt channel: every user message and model reply is persisted and a
// chained "prompt" event marks the exchange. Payload is candidate-controlled:
// coerce hard, cap sizes.
//
// Perf pass: the transcript sent to the model is now capped to the most recent
// turns (the Python side already clips to 30 â€” sending the full history was pure
// wasted serialization), and the currentFile payload cap is aligned with what the
// model prompt actually consumes (4k) instead of 64k.

const MAX_MESSAGE_CHARS = 4_000;
const MAX_TRANSCRIPT_MSGS = 30;
const MAX_FILE_CHARS = 4_000;

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const session = getDevSession(id);
    if (!session) return NextResponse.json({ error: "session not found" }, { status: 404 });
    if (session.status !== "active") return NextResponse.json({ error: "session already submitted" }, { status: 409 });

    const body = (await request.json().catch(() => ({}))) as {
      channel?: unknown;
      message?: unknown;
      currentFile?: unknown;
    };
    const channel = body.channel === "stakeholder" ? "stakeholder" : "assistant";
    const message = typeof body.message === "string" ? body.message.trim().slice(0, MAX_MESSAGE_CHARS) : "";
    if (!message) return NextResponse.json({ error: "message is required" }, { status: 400 });
    const cf = body.currentFile as { path?: unknown; contents?: unknown } | null | undefined;
    const currentFile =
      channel === "assistant" && cf && typeof cf.path === "string" && typeof cf.contents === "string"
        ? { path: cf.path, contents: cf.contents.slice(0, MAX_FILE_CHARS) }
        : null;

    const posting = session.token ? getPostingByToken(session.token) : null;
    const devCase = posting?.caseId ? getDevCase(posting.caseId) : null;
    if (!devCase?.case) return NextResponse.json({ error: "case unavailable" }, { status: 404 });

    // Only the most recent turns are model context; the stored copy remains the
    // full evaluation evidence.
    const transcript = getDevSessionChat(id, channel)
      .slice(-MAX_TRANSCRIPT_MSGS)
      .map((m) => ({ channel: m.channel, role: m.role, text: m.text }));
    const stored = appendDevSessionChat(id, channel, "user", message);
    if (stored === 0) return NextResponse.json({ error: "chat limit reached for this session" }, { status: 429 });
    appendDevSessionEvents(id, [{ t: Date.now(), kind: "prompt", path: channel, size: message.length }]);

    const lang = posting ? lifecycleByPosting(posting.id)?.lang : null;
    const { reply } = await runSessionChat(
      channel,
      (devCase.case as Record<string, unknown>) ?? {},
      (devCase.role as Record<string, unknown>) ?? {},
      transcript.concat([{ channel, role: "user", text: message }]),
      message,
      currentFile,
      lang
    );
    if (reply) appendDevSessionChat(id, channel, "model", reply);
    return NextResponse.json({ reply });
  } catch (error) {
    return jsonError(error, "Failed to reach the chat channel.");
  }
}

import { NextResponse } from "next/server";
import {
  appendDevSessionEvents,
  getDevCase,
  getDevSession,
  getDevSessionEvents,
  getPostingByToken,
  saveDevSessionFiles,
} from "@/app/_lib/db";
import { jsonError } from "@/app/_lib/api-response";

// Live Work Surface flush â€” append observed events + save the seed tree.
//
// Perf pass: the mid-flight-update block previously ran getPostingByToken +
// getDevCase + a full getDevSessionEvents scan on EVERY flush (every 8s per
// active session) even when the case has no midFlightUpdate or the reveal isn't
// due yet. The case lookup is unavoidable (we need afterMinutes), but the
// events-table scan is now only performed once the reveal is actually due, and
// empty flushes short-circuit before touching the files table.
const KINDS = new Set(["open", "edit", "decision_log", "submit", "paste"]);
const MAX_EVENTS = 500; // per flush
const MAX_FILES = 50;
const MAX_FILE_BYTES = 256 * 1024;

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const session = getDevSession(id);
    if (!session) return NextResponse.json({ error: "session not found" }, { status: 404 });
    if (session.status !== "active") return NextResponse.json({ error: "session already submitted" }, { status: 409 });

    const body = (await request.json().catch(() => ({}))) as { events?: unknown; files?: unknown };

    let seq = 0;
    if (Array.isArray(body.events) && body.events.length > 0) {
      const events = body.events
        .slice(0, MAX_EVENTS)
        .filter((e): e is Record<string, unknown> => !!e && typeof e === "object")
        .filter((e) => KINDS.has(String(e.kind)))
        .map((e) => ({
          t: Number(e.t) || 0,
          kind: String(e.kind),
          path: typeof e.path === "string" ? e.path : null,
          size: Number.isFinite(Number(e.size)) ? Number(e.size) : null,
        }));
      if (events.length > 0) seq = appendDevSessionEvents(id, events);
    }

    if (Array.isArray(body.files) && body.files.length > 0) {
      const files = body.files
        .filter((f): f is Record<string, unknown> => !!f && typeof f === "object" && typeof f.path === "string")
        .slice(0, MAX_FILES)
        .map((f) => ({ path: String(f.path), contents: String(f.contents ?? "").slice(0, MAX_FILE_BYTES) }));
      saveDevSessionFiles(id, files);
    }

    // Mid-flight update reveal: serve the requirement change once due, recording
    // the reveal server-side as a chained "perturbation" event. The events scan
    // only runs when the reveal window has opened â€” before that, `fired` cannot
    // be true (the event is server-written and only written when due).
    let perturbation: string | null = null;
    const kase = session.token ? (getDevCase(getPostingByToken(session.token)?.caseId ?? "")?.case as
      | { midFlightUpdate?: { afterMinutes?: number; update?: string } }
      | null) : null;
    const mfu = kase?.midFlightUpdate;
    if (mfu?.update && typeof mfu.afterMinutes === "number") {
      const due = Date.now() - Date.parse(session.createdAt) >= mfu.afterMinutes * 60_000;
      if (due) {
        const fired = getDevSessionEvents(id).some((e) => e.kind === "perturbation");
        if (!fired) appendDevSessionEvents(id, [{ t: Date.now(), kind: "perturbation", path: null }]);
        perturbation = mfu.update;
      }
    }

    return NextResponse.json({ ok: true, seq, perturbation });
  } catch (error) {
    return jsonError(error, "Failed to save the work session.");
  }
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { TextInput } from "@/app/_components/TextInput";
import type { ProcessEvent, SeedFile } from "@/app/features/sub_dev/DevTypes";
import { draftStorageKey, encodeDraft, decodeDraft, type LiveWorkDraft } from "./liveWorkDraft";

// Live Work Surface â€” in-product editor over the materialized seed. Records
// observed process events and flushes them + the file tree to the session.
//
// Perf pass: flushes are now DIRTY-AWARE. Previously every 8s tick posted the
// FULL file tree (up to 50 files x 256KB) even when nothing changed â€” the bulk
// of the per-request cost on the flush path. Now: events flush only when the
// pending buffer is non-empty, and files are included only when an edit has
// occurred since the last successful flush. An empty tick (no events, no dirty
// files) still fires a lightweight flush so the perturbation reveal channel
// keeps polling â€” but with an empty body doing no DB writes server-side.

const DECISIONS_FILE = "DECISIONS.md";
const FLUSH_MS = 8000;
const EDIT_DEBOUNCE_MS = 600;

export function LiveWorkSurface({ token, seedFiles, note }: { token: string; seedFiles: SeedFile[]; note: string | null }) {
  const t = useTranslations("devApply.workSurface");
  const [files, setFiles] = useState<SeedFile[]>(() => seedFiles.map((f) => ({ ...f })));
  const [activePath, setActivePath] = useState<string>(seedFiles[0]?.path ?? "");
  const [status, setStatus] = useState<"idle" | "submitting" | "submitted" | "error">("idle");

  const tApply = useTranslations("devApply");
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const contactValid = /\S+@\S+\.\S+/.test(contact.trim());
  const canSubmit = name.trim().length > 0 && contactValid && status !== "submitting";

  const sessionIdRef = useRef<string | null>(null);
  const startingRef = useRef(false);
  const submittingRef = useRef(false);
  const pendingRef = useRef<ProcessEvent[]>([]);
  const filesRef = useRef(files);
  const dirtyRef = useRef(false);
  const [perturbation, setPerturbation] = useState<string | null>(null);

  const [restored, setRestored] = useState(false);
  const persistDraft = useCallback(() => {
    if (typeof window === "undefined") return;
    try {
      const draft: LiveWorkDraft = {
        sessionId: sessionIdRef.current,
        files: filesRef.current,
        pending: pendingRef.current,
        savedAt: Date.now(),
      };
      window.localStorage.setItem(draftStorageKey(token), encodeDraft(draft));
    } catch {}
  }, [token]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const draft = decodeDraft(window.localStorage.getItem(draftStorageKey(token)));
    if (!draft) return;
    if (draft.files.length > 0) { setFiles(draft.files); dirtyRef.current = true; }
    if (draft.sessionId) sessionIdRef.current = draft.sessionId;
    pendingRef.current = draft.pending;
    if (draft.files.length > 0 || draft.pending.length > 0) setRestored(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once on mount only
  }, []);

  useEffect(() => {
    filesRef.current = files;
    persistDraft();
  }, [files, persistDraft]);
  const editTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const ensureSession = useCallback(async (): Promise<string | null> => {
    if (sessionIdRef.current) return sessionIdRef.current;
    if (startingRef.current) return null;
    startingRef.current = true;
    try {
      const r = await fetch("/api/devcase/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token }),
      });
      if (!r.ok) return null;
      const data = (await r.json()) as { sessionId?: string; watermark?: string };
      sessionIdRef.current = data.sessionId ?? null;
      if (data.watermark) {
        setFiles((prev) =>
          prev.map((f) =>
            f.path === DECISIONS_FILE
              ? { ...f, contents: f.contents.replace(/<!-- session:[^>]* -->\n?/g, "") + `\n<!-- session:${data.watermark} -->\n` }
              : f
          )
        );
      }
      return sessionIdRef.current;
    } finally {
      startingRef.current = false;
    }
  }, [token]);

  const record = useCallback((e: ProcessEvent) => {
    pendingRef.current.push(e);
    persistDraft();
    void ensureSession();
  }, [ensureSession, persistDraft]);

  const flush = useCallback(async () => {
    const id = sessionIdRef.current;
    if (!id) return;
    const events = pendingRef.current.splice(0, pendingRef.current.length);
    const includeFiles = dirtyRef.current;
    if (includeFiles) dirtyRef.current = false;
    try {
      const r = await fetch(`/api/devcase/session/${id}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          events: events.length ? events : undefined,
          files: includeFiles ? filesRef.current : undefined,
        }),
      });
      if (!r.ok) throw new Error(String(r.status));
      const data = (await r.json()) as { perturbation?: string | null };
      if (data.perturbation) setPerturbation(data.perturbation);
      persistDraft();
    } catch {
      // Failed flush: restore events + dirty flag so the next tick retries.
      pendingRef.current = events.concat(pendingRef.current);
      if (includeFiles) dirtyRef.current = true;
      persistDraft();
    }
  }, [persistDraft]);

  useEffect(() => {
    const iv = setInterval(() => void flush(), FLUSH_MS);
    return () => clearInterval(iv);
  }, [flush]);

  const onEdit = useCallback((path: string, contents: string) => {
    setFiles((prev) => prev.map((f) => (f.path === path ? { ...f, contents } : f)));
    dirtyRef.current = true;
    if (editTimer.current) clearTimeout(editTimer.current);
